package org.sleepwell.app;

import android.content.*;import android.graphics.*;import android.view.View;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import org.junit.*;import org.junit.runner.RunWith;import java.time.*;import java.util.*;import static org.junit.Assert.*;

/** Real private record/projection/chart resources, no service, physical sensor or provider. */
@RunWith(AndroidJUnit4.class)
public final class RecordInsightsNativeTest {
    Context c;String name;SharedPreferences prefs;
    @Before public void setup(){c=InstrumentationRegistry.getInstrumentation().getTargetContext();name="record-insights-"+UUID.randomUUID();prefs=c.getSharedPreferences(name,0);}
    @After public void cleanup(){c.deleteDatabase(name);c.deleteSharedPreferences(name);}
    @Test public void savedEffectiveRecordsAndFrozenGoalsReopenWithoutMutatingOriginals(){Instant now=Instant.parse("2026-10-26T18:00:00Z");String before;try(Store store=new Store(c,name)){long start=Instant.parse("2026-10-20T00:00:00Z").toEpochMilli();RecordDraft draft=new RecordDraft(start,start+8*3600000L);draft.awake.add(new RecordIntervals.Span(start,start+3600000L));Records.create(store,draft,ZoneId.of("UTC"),now.toEpochMilli());before=store.backup().toString();}GoalCommitment goal=new GoalCommitment("33ae54e2-e661-4f89-b623-e175159c12d6","duration",480,LocalDate.of(2026,10,19),14,"UTC",0,"",null);try(Store reopened=new Store(c,name)){RecordInsights result=new RecordInsights(Records.all(reopened),List.of(goal),LocalDate.of(2026,10,25),7,0,now);assertEquals(1,result.observed);assertEquals(7*3600000L,(long)result.average);assertEquals(-3600000L,result.goal.balance);assertEquals(before,reopened.backup().toString());}}
    @Test public void savedWindowPersistsAndInvalidValuesAreVisibleErrors(){assertEquals(30,RecordInsightSettings.days(prefs));RecordInsightSettings.save(prefs,90);assertEquals(90,RecordInsightSettings.days(c.getSharedPreferences(name,0)));Map<String,?> before=new HashMap<>(prefs.getAll());assertThrows(IllegalArgumentException.class,()->RecordInsightSettings.save(prefs,365));assertEquals(before,prefs.getAll());assertTrue(prefs.edit().putInt("days",365).commit());assertThrows(IllegalArgumentException.class,()->RecordInsightSettings.days(prefs));assertEquals(365,prefs.getInt("days",0));}
    @Test public void nativeChartsExposeUnknownDatesAndDistinctActualMetrics(){long start=Instant.parse("2026-10-20T00:00:00Z").toEpochMilli();RecordDraft draft=new RecordDraft(start,start+7*3600000L);RecordEntry record=new RecordEntry(1,start,draft.end,null,"manual","local","UTC",0,0,draft,true,0,List.of());RecordInsights result=new RecordInsights(List.of(record),List.of(),LocalDate.of(2026,10,25),7,0,Instant.parse("2026-10-26T18:00:00Z"));InstrumentationRegistry.getInstrumentation().runOnMainSync(()->{RecordInsightsChart duration=new RecordInsightsChart(c,result,0),goals=new RecordInsightsChart(c,result,1),timing=new RecordInsightsChart(c,result,2);assertTrue(duration.getContentDescription().toString().contains("2026-10-20: 7 h 0 min"));assertTrue(duration.getContentDescription().toString().contains("2026-10-19: unknown"));assertTrue(goals.getContentDescription().toString().contains("2026-10-20: unknown"));assertTrue(timing.getContentDescription().toString().contains("2026-10-20: 00:00"));duration.measure(View.MeasureSpec.makeMeasureSpec(800,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(420,View.MeasureSpec.EXACTLY));duration.layout(0,0,800,420);Bitmap image=Bitmap.createBitmap(800,420,Bitmap.Config.ARGB_8888);duration.draw(new Canvas(image));int[] pixels=new int[800*420];image.getPixels(pixels,0,800,0,0,800,420);boolean ink=false;for(int pixel:pixels)if(Color.alpha(pixel)>0){ink=true;break;}assertTrue(ink);image.recycle();});}
}
